	REX_STORE_U32(ctx.r1.u32 + -8, ctx.r12.u32);
	// std r30,-24(r1)
	REX_STORE_U64(ctx.r1.u32 + -24, ctx.r30.u64);
	// std r31,-16(r1)
	REX_STORE_U64(ctx.r1.u32 + -16, ctx.r31.u64);
	// stwu r1,-112(r1)
	ea = -112 + ctx.r1.u32;
	REX_STORE_U32(ea, ctx.r1.u32);
	ctx.r1.u32 = ea;
	// mr r30,r3
	ctx.r30.u64 = ctx.r3.u64;
	// lwz r11,9608(r30)
	ctx.r11.u64 = REX_LOAD_U32(ctx.r30.u32 + 9608);
	// cmpwi cr6,r11,0
	ctx.cr6.compare<int32_t>(ctx.r11.s32, 0, ctx.xer);
	// bne cr6,0x8218c2c4
	if (!ctx.cr6.eq) goto loc_8218C2C4;
	// li r3,0
	ctx.r3.s64 = 0;
	// bl 0x8211c068
	ctx.lr = 0x8218C26C;
	sub_8211C068(ctx, base);
	// cmpwi r3,0
	ctx.cr0.compare<int32_t>(ctx.r3.s32, 0, ctx.xer);
	// beq 0x8218c2c4
	if (ctx.cr0.eq) goto loc_8218C2C4;
	// li r3,9
	ctx.r3.s64 = 9;
	// bl 0x8211c068
	ctx.lr = 0x8218C27C;
	sub_8211C068(ctx, base);
	// cmpwi r3,0
	ctx.cr0.compare<int32_t>(ctx.r3.s32, 0, ctx.xer);
	// beq 0x8218c2c4
	if (ctx.cr0.eq) goto loc_8218C2C4;
	// li r3,10
	ctx.r3.s64 = 10;
	// bl 0x8211c068
	ctx.lr = 0x8218C28C;
	sub_8211C068(ctx, base);
	// cmpwi r3,0
	ctx.cr0.compare<int32_t>(ctx.r3.s32, 0, ctx.xer);
	// beq 0x8218c2c4
	if (ctx.cr0.eq) goto loc_8218C2C4;
	// lis r11,-32148
	ctx.r11.s64 = -2106851328;
	// lwz r7,32448(r11)
	ctx.r7.u64 = REX_LOAD_U32(ctx.r11.u32 + 32448);
	// mr r3,r7
	ctx.r3.u64 = ctx.r7.u64;
	// bl 0x8218c0f8
	ctx.lr = 0x8218C2A4;
	sub_8218C0F8(ctx, base);
	// cmpwi r3,0
	ctx.cr0.compare<int32_t>(ctx.r3.s32, 0, ctx.xer);
